import Foundation

struct Product: Codable, Identifiable {
    let id: Int
    let name: String
    let price: Decimal
}

struct ProductCatalog {
    private(set) var products: [Product] = []
    mutating func replace(with products: [Product]) { self.products = products }
    func search(_ query: String) -> [Product] {
        products.filter { $0.name.localizedCaseInsensitiveContains(query) }
    }
}

let fixture = #"[{"id":1,"name":"Notebook","price":12.5},{"id":2,"name":"Pen","price":2.0}]"#.data(using: .utf8)!
var catalog = ProductCatalog()
catalog.replace(with: try JSONDecoder().decode([Product].self, from: fixture))
print(catalog.search("note").map(\.name))
